# All autotune configs have BLOCK_M >= 128 AND BLOCK_N >= 128
# Accumulator = 128*128*4 = 65,536 bytes -> 255 regs/thread, 2 blocks/SM
@triton.autotune(configs=[
    triton.Config({'BLOCK_M': 128, 'BLOCK_N': 128, 'BLOCK_K': 32, 'GROUP_M': 8}, num_stages=3, num_warps=4),
    triton.Config({'BLOCK_M': 256, 'BLOCK_N': 128, 'BLOCK_K': 32, 'GROUP_M': 8}, num_stages=3, num_warps=8),
    # ... all configs with BLOCK_M >= 128 AND BLOCK_N >= 128
], key=['M', 'N', 'K'])
@triton.jit
def kernel(...):
    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)  # 65KB accumulator
    for k in range(0, K, BLOCK_K):
        acc = tl.dot(x_tile, w_tile, acc, input_precision='tf32x3')

