# -> 255 regs/thread (hardware max), local memory spill, MemoryCacheAccessPattern ~53%
@triton.autotune(configs=[
    triton.Config({'BLOCK_M': 128, 'BLOCK_N': 128, 'BLOCK_K': 32, 'GROUP_M': 8}, num_stages=3, num_warps=4),
    triton.Config({'BLOCK_M': 256, 'BLOCK_N': 128, 'BLOCK_K': 32, 'GROUP_M': 8}, num_stages=1, num_warps=8),
    # ... all configs with BLOCK_M*BLOCK_N >= 128*128
], key=['M', 'N', 'K'])
def kernel(...):
    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)  # 128*128 = 16384 elements
    for k in range(0, tl.cdiv(K, BLOCK_K)):
        acc = tl.dot(x_tile, w_tile, acc, input_precision='tf32x3')

